CustomField.formula:
/* Time spent in Nurturing */

 /* WEEKS */
IF(
    FLOOR(Time_spent_in_Nurturing__c / 10080) > 0,
    TEXT(FLOOR(Time_spent_in_Nurturing__c / 10080)) &
    IF(FLOOR(Time_spent_in_Nurturing__c / 10080) = 1, " Week ", " Weeks "),
    ""
) &

 /* DAYS */
IF(
    FLOOR(MOD(Time_spent_in_Nurturing__c, 10080) / 1440) > 0,
    TEXT(FLOOR(MOD(Time_spent_in_Nurturing__c, 10080) / 1440)) &
    IF(FLOOR(MOD(Time_spent_in_Nurturing__c, 10080) / 1440) = 1, " Day ", " Days "),
    ""
) &

 /* HOURS */
IF(
    FLOOR(MOD(Time_spent_in_Nurturing__c, 1440) / 60) > 0,
    TEXT(FLOOR(MOD(Time_spent_in_Nurturing__c, 1440) / 60)) &
    IF(FLOOR(MOD(Time_spent_in_Nurturing__c, 1440) / 60) = 1, " Hour ", " Hours "),
    ""
) &

 /* MINUTES — only if >= 1 (no decimals) */
IF(
    FLOOR(MOD(Time_spent_in_Nurturing__c, 60)) > 0,
    TEXT(FLOOR(MOD(Time_spent_in_Nurturing__c, 60))) &
    IF(FLOOR(MOD(Time_spent_in_Nurturing__c, 60)) = 1, " Minute", " Minutes"),
    ""
)
